```python
import os
from flask import Flask, request, redirect, session, jsonify
import requests
from urllib.parse import urlencode, parse_qs, urlparse

app = Flask(__name__)
app.secret_key = os.urandom(24)

# Auth0 Configuration
AUTH0_DOMAIN = os.getenv('AUTH0_DOMAIN', 'your-auth0-domain.auth0.com')
AUTH0_CLIENT_ID = os.getenv('AUTH0_CLIENT_ID', 'your-client-id')
AUTH0_CLIENT_SECRET = os.getenv('AUTH0_CLIENT_SECRET', 'your-client-secret')
REDIRECT_URI = 'http://localhost:5000/callback'

def generate_code_verifier():
    import secrets
    return secrets.token_urlsafe(64)

def generate_code_challenge(code_verifier):
    import base64
    import hashlib
    hashed = hashlib.sha256(code_verifier.encode('utf-8')).digest()
    return base64.urlsafe_b64encode(hashed).decode('utf-8').replace('=', '')

@app.route('/login')
def login():
    code_verifier = generate_code_verifier()
    code_challenge = generate_code_challenge(code_verifier)

    session['code_verifier'] = code_verifier

    params = {
        'client_id': AUTH0_CLIENT_ID,
        'response_type': 'code',
        'scope': 'openid profile email',
        'redirect_uri': REDIRECT_URI,
        'code_challenge': code_challenge,
        'code_challenge_method': 'S256'
    }

    auth_url = f'https://{AUTH0_DOMAIN}/authorize?'
    return redirect(auth_url + urlencode(params))

@app.route('/callback')
def callback():
    if 'code' not in request.args:
        return 'Authorization failed', 400

    code = request.args['code']
    code_verifier = session.get('code_verifier')

    if not code_verifier:
        return 'Missing code verifier', 400

    token_url = f'https://{AUTH0_DOMAIN}/oauth/token'
    payload = {
        'client_id': AUTH0_CLIENT_ID,
        'client_secret': AUTH0_CLIENT_SECRET,
        'code': code,
        'redirect_uri': REDIRECT_URI,
        'grant_type': 'authorization_code',
        'code_verifier': code_verifier
    }

    response = requests.post(token_url, json=payload)
    if response.status_code != 200:
        return f'Token exchange failed: {response.text}', response.status_code

    token_data = response.json()
    access_token = token_data.get('access_token')

    if not access_token:
        return 'No access token received', 400

    userinfo_url = f'https://{AUTH0_DOMAIN}/userinfo'
    headers = {'Authorization': f'Bearer {access_token}'}
    userinfo_response = requests.get(userinfo_url, headers=headers)

    if userinfo_response.status_code != 200:
        return f'Userinfo request failed: {userinfo_response.text}', userinfo_response.status_code

    userinfo = userinfo_response.json()

    session['user'] = userinfo
    return redirect('/profile')

@app.route('/profile')
def profile():
    user = session.get('user')
    if not user:
        return redirect('/login')

    return jsonify({
        'status': 'authenticated',
        'user': user
    })

@app.route('/logout')
def logout():
    session.clear()
    return redirect(f'https://{AUTH0_DOMAIN}/v2/logout?client_id={AUTH0_CLIENT_ID}&returnTo={REDIRECT_URI}')

if __name__ == '__main__':
    app.run(debug=True)
